def choose_move(observation):
    # Defensive defaults
    pos = observation.get("position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    # Initialize with stay
    dx = 0
    dy = 0

    # Look for resources/enemies/territory hints with safe defaults
    grid = observation.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Helper to peek safely
    def val_at(nx, ny):
        if 0 <= ny < height and 0 <= nx < width:
            row = grid[ny]
            if 0 <= ny < len(grid) and 0 <= nx < len(row):
                return grid[ny][nx]
        return None

    # Simple robust heuristic:
    #  - If a resource cell nearby, move toward it
    #  - Else if an opponent/entity nearby, move away if possible
    #  - Else try to drift toward center/away from edges
    best_dx = 0
    best_dy = 0
    best_score = -10

    # Scan a 3x3 neighborhood
    for oy in (-1, 0, 1):
        for ox in (-1, 0, 1):
            if ox == 0 and oy == 0:
                continue
            cell = val_at(x + ox, y + oy)
            score = 0
            if cell is None:
                continue
            if isinstance(cell, str):
                c = cell.lower()
                if "resource" in c or "food" in c or "gold" in c or "tree" in c:
                    score = 2
                if "enemy" in c or "opponent" in c or "evader" in c:
                    score = -2
                if "territory" in c or "flag" in c:
                    score = 1
            elif isinstance(cell, dict):
                # gradient from cell type tags
                t = cell.get("type", "")
                if t in ("resource", "food", "gold"):
                    score = 2
                if t in ("enemy", "opponent", "evader"):
                    score = -2
            # Prefer closer to resource, away from threat
            if score > best_score:
                best_score = score
                best_dx = ox
                best_dy = oy

    # If a positive cue found, take that direction
    if best_score > 0:
        dx, dy = best_dx, best_dy
    else:
        # No positive cue; keep near center to avoid edges
        center_dx = 0
        center_dy = 0
        if x > 0:
            center_dx = -1
        if x < (width - 1 if width else 0):
            center_dx = 1 if center_dx == 0 else center_dx
        if y > 0:
            center_dy = -1
        if y < (height - 1 if height else 0):
            center_dy = 1 if center_dy == 0 else center_dy
        dx, dy = center_dx, center_dy

    # Clip to allowed moves
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

